Let $X$ be a scheme satisfying (\dag), $\delta \colon X \to \mathbb{Z}$ a dimension function. A \emph{potential dualizing complex} (in coefficient $\Lambda$) on $X$ consisting of
	\begin{enumerate}
		\item an object $\mathscr{K}$ in $\mathbf{D}_{\mathrm{c}}\@ifempty{\textbf{+}}{}{^{\textbf{+}}}\@ifnextchar({\b@Brac}{\n@Brac}{X_{\textup{\'et}}, \Lambda}$,
		\item an isomorphism $\mathbf{R}\@ifempty{}{}{^{}} \varGamma_x(\mathscr{K})  
  \@ifempty{}{\xrightarrow{\,\sim\,}} 
  {\xrightarrow[\,\sim\,]{}} 
 \Lambda\bigl(\delta(x)\bigr)\bigl[2\delta(x)\bigr]$ in $\mathbf{D}_{\mathrm{c}}\@ifempty{\textbf{+}}{}{^{\textbf{+}}}\@ifnextchar({\b@Brac}{\n@Brac}{x_{\textup{\'et}}, \Lambda}$ for every point $x$ on $X$;
	\end{enumerate}
	and these data satisfy that: for every immediate specialization $\bar{y} \to \bar{x}$ on $X$, the following diagram commutes,
	\[ \xymatrix@C+2em{\mathbf{R}\@ifempty{}{}{^{}} \varGamma_{\bar{y}}(\mathscr{K}) \ar[r]^-{\mathrm{sp}^X_{\bar{y} \to \bar{x}}} \ar[d]_-{\cong}
			& \mathbf{R}\@ifempty{}{}{^{}} \varGamma_{\bar{x}}(\mathscr{K})(1)[2] \ar[d]^-{\cong} \\
		R\bigl(\delta(y)\bigr)\bigl[2\delta(y)\bigr] \ar@{=}[r] & R\bigl(\delta(x)+1\bigr)\bigl[2(\delta(x)+1)\bigr]} \]
	where $\mathrm{sp}^X_{\bar{y} \to \bar{x}}$ is the transition morphism of codimension $1$ defined in \cite[\S1]{JRiou1}.

\label{T-P0}
	Let $X$ be a scheme satisfying (\dag) equipped with a dimension function $\delta$, $Y$ a closed subscheme of $X$ and $U \mathrel{\mathop:}= X \setminus Y$. Then there is a long exact sequence of $\Lambda$-modules:
	\[ \cdots \mathrm{H}_{n+1}(U, \delta) \to \mathrm{H}_{n}(Y, \delta) \to \mathrm{H}_{n}(X, \delta) \to \mathrm{H}_{n}(U, \delta) \to \mathrm{H}_{n-1}(Y, \delta) \to \cdots \,. \]

\label{T-P1}
	Let $X$ be a scheme satisfying (\dag) equipped with a dimension function $\delta$, $X_1$ and $X_2$ two closed subschemes of $X$ such that $X = X_1 \cup X_2$ (as sets). Then we have a long exact sequence
	\[ \cdots \to \mathrm{H}_{n}(X_1 \cap X_2, \, \delta) \to \mathrm{H}_{n}(X_1, \delta) \oplus \mathrm{H}_{n}(X_2, \delta) \to \mathrm{H}_{n}(X, \delta) \to \mathrm{H}_{n-1}(X_1 \cap X_2, \, \delta) \to \cdots \,. \]

\label{53P2}
	Let $X$ be a scheme satisfying (\dag) equipped with a dimension function $\delta$, $Y$ a closed subscheme of $X$, $X' \mathrel{\mathop:}= X \setminus Y$. Then for each integer $n > 2 \dim_{\delta}(Y) + 1$, there is a canonical isomorphism $\mathrm{H}_{n}(X, \delta)  
  \@ifempty{}{\xrightarrow{\,\sim\,}} 
  {\xrightarrow[\,\sim\,]{}} 
 \mathrm{H}_{n}(X', \delta)$ of $\Lambda$-modules.

Let $X$ be a scheme satisfying (\dag) equipped with a dimension function $\delta$, $d \mathrel{\mathop:}= \dim_{\delta}(X)$.
	\begin{enumerate}
		\item First we assume that $X$ is regular and integral. Then we use $\mathrm{t}_X \colon \Lambda  
  \@ifempty{}{\xrightarrow{\,\sim\,}} 
  {\xrightarrow[\,\sim\,]{}} 
 \mathscr{K}_{X, \delta}(-d)[-2d]$ to denote the canonical morphism defined by \autoref{236P2}, and use $\mathrm{cl}(X)$ to denote the element in $\mathrm{H}_{2d}(X, \delta)(-d)$ corresponding to $\mathrm{t}_X$.
		\item Second we only assume that $X$ is integral. As $X$ is excellent, $U \mathrel{\mathop:}= X_{\mathrm{reg}}$ is an open dense subset of $X$. Obviously $\dim_{\delta}(X \setminus U) < d$. By \autoref{53P2}, there is a canonical isomorphism
			\[ \mathrm{H}_{2d}(X, \delta)(-d)  
  \@ifempty{}{\xrightarrow{\,\sim\,}} 
  {\xrightarrow[\,\sim\,]{}} 
 \mathrm{H}_{2d}(U, \delta)(-d) \,. \]
			Let $\mathrm{cl}(X)$ be the inverse image of $\mathrm{cl}(U)$ under above isomorphism.
		\item In general case, we let $X_1, X_2, \ldots, X_r$ be all irreducible components of $X$ with $\dim_{\delta}(X_i) = d$. For each $i$, regard $X_i$ as a reduced subscheme of $X$, let $\iota_i \colon X_i \hookrightarrow X$ be the inclusion and let $\xi_i$ be the generic point of $X_i$. Then we define
			\[ \mathrm{cl}(X) \mathrel{\mathop:}= \sum^r_{i=1} \mathrm{length}(\mathcal{O}_{X, \xi_i}) \cdot \iota_{i, \ast} \bigl(\mathrm{cl}(X_i)\bigr) \in \mathrm{H}_{2d}(X, \delta)(-d) \,. \]
			We also use $\mathrm{t}_X \colon \Lambda  
  \@ifempty{}{\xrightarrow{\,\sim\,}} 
  {\xrightarrow[\,\sim\,]{}} 
 \mathscr{K}_{X, \delta}(-d)[-2d]$ to denote the morphism in $\mathbf{D}_{\mathrm{c}}\@ifempty{\mathrm{b}}{}{^{\mathrm{b}}}\@ifnextchar({\b@Brac}{\n@Brac}{X, \Lambda}$ corresponding to $\mathrm{cl}(X)$.
	\end{enumerate}

\label{194L0}
	Let $X$ be a scheme satisfying (\dag), $Y$ a closed subscheme of $X$, $U \mathrel{\mathop:}= X \setminus Y$, $i \colon Y \hookrightarrow X$ and $j \colon U \hookrightarrow X$ the inclusions. Then for each object $\mathscr{F}$ in $\mathbf{D}_{\mathrm{c}}\@ifempty{\mathrm{b}}{}{^{\mathrm{b}}}\@ifnextchar({\b@Brac}{\n@Brac}{X_{\textup{\'et}}, \Lambda}$, there are two distinguished triangles in $\mathbf{D}_{\mathrm{c}}\@ifempty{\mathrm{b}}{}{^{\mathrm{b}}}\@ifnextchar({\b@Brac}{\n@Brac}{X_{\textup{\'et}}, \Lambda}$:
	\begin{enumerate}
		\item $j_!j^{\ast}\mathscr{F} \to \mathscr{F} \to i_{\ast}i^{\ast}\mathscr{F} \to j_!j^{\ast}\mathscr{F}[1]$\,,
		\item $i_{\ast}\mathbf{R}\@ifempty{}{}{^{}} i^!\mathscr{F} \to \mathscr{F} \to \mathbf{R}\@ifempty{}{}{^{}} j_{\ast} j^{\ast}\mathscr{F} \to i_{\ast}\mathbf{R}\@ifempty{}{}{^{}} i^!\mathscr{F}[1]$\,.
	\end{enumerate}

Let $X$ be a scheme satisfying (\dag), $Y$ a closed subscheme of $X$, $U \mathrel{\mathop:}= X \setminus Y$, $i \colon Y \hookrightarrow X$ and $j \colon U \hookrightarrow X$ the inclusions, $\mathscr{F}' \xrightarrow{\varphi} \mathscr{F} \xrightarrow{\psi} \mathscr{F}''$ a sequence of objects in $\mathbf{D}_{\mathrm{c}}\@ifempty{\mathrm{b}}{}{^{\mathrm{b}}}\@ifnextchar({\b@Brac}{\n@Brac}{X_{\textup{\'et}}, \Lambda}$. Assume that one of the following two conditions holds:
	\begin{enumerate}
		\item $j^{\ast}(\varphi) \colon j^{\ast}\mathscr{F}'  
  \@ifempty{}{\xrightarrow{\,\sim\,}} 
  {\xrightarrow[\,\sim\,]{}} 
 j^{\ast}\mathscr{F}$ is an isomorphism, $j^{\ast}\mathscr{F}'' = 0$, and for all $n \in \mathbb{Z}$,
			\[ 0 \to \mathrm{H}^{n}(i^{\ast}\mathscr{F}') \to \mathrm{H}^{n}(i^{\ast}\mathscr{F}) \to  \mathrm{H}^{n}(i^{\ast}\mathscr{F}'') \to 0 \]
			is a short exact sequence;
		\item $j^{\ast}(\psi) \colon j^{\ast}\mathscr{F}  
  \@ifempty{}{\xrightarrow{\,\sim\,}} 
  {\xrightarrow[\,\sim\,]{}} 
 j^{\ast}\mathscr{F}''$ is an isomorphism, $j^{\ast}\mathscr{F}' = 0$, and for all $n \in \mathbb{Z}$,
			\[ 0 \to \mathrm{H}^{n}(\mathbf{R}\@ifempty{}{}{^{}} i^!\mathscr{F}') \to \mathrm{H}^{n}(\mathbf{R}\@ifempty{}{}{^{}} i^!\mathscr{F}) \to  \mathrm{H}^{n}(\mathbf{R}\@ifempty{}{}{^{}} i^!\mathscr{F}'') \to 0 \]
			is a short exact sequence.
	\end{enumerate}
	Then there exists a morphism $\delta \colon \mathscr{F}'' \to \mathscr{F}'[1]$ which makes
	\[ \mathscr{F}' \xrightarrow{\varphi} \mathscr{F} \xrightarrow{\psi} \mathscr{F}'' \xrightarrow{\delta} \mathscr{F}'[1] \]
	a distinguished triangle in $\mathbf{D}_{\mathrm{c}}\@ifempty{\mathrm{b}}{}{^{\mathrm{b}}}\@ifnextchar({\b@Brac}{\n@Brac}{X_{\textup{\'et}}, \Lambda}$.

The morphism $\varphi$ extends to a distinguished triangle
	\[ \mathscr{F}' \xrightarrow{\varphi} \mathscr{F} \xrightarrow{\phi} \mathscr{G} \xrightarrow{\rho} \mathscr{F}'[1] \]
	in $\mathbf{D}_{\mathrm{c}}\@ifempty{\mathrm{b}}{}{^{\mathrm{b}}}\@ifnextchar({\b@Brac}{\n@Brac}{X_{\textup{\'et}}, \Lambda}$. Note that $0 \to \mathscr{F}'' \xrightarrow{\mathrm{id}} \mathscr{F}'' \to 0[1]$ is also a distinguished triangle. Hence there exists a morphism $\alpha \colon \mathscr{G} \to \mathscr{F}''$ such that the triple $(0, \psi, \alpha)$ is a morphism of distinguished triangles, i.e., the following diagram commutes.
	\[ \xymatrix{\mathscr{F}' \ar[r]^-{\varphi} \ar[d]^{0} & \mathscr{F} \ar[r]^-{\phi} \ar[d]^{\psi} & \mathscr{G} \ar[r]^-{\rho} \ar[d]^{\alpha} & \mathscr{F}'[1] \ar[d]^{0} \\
		0 \ar[r] & \mathscr{F}'' \ar[r]^-{\mathrm{id}} & \mathscr{F}'' \ar[r] & 0[1]} \]

	Now if (1) holds, then both $j^{\ast}(\alpha)$ and $i^{\ast}(\alpha)$ are isomorphic; and if (2) holds, then both $j^{\ast}(\alpha)$ and $\mathbf{R}\@ifempty{}{}{^{}} i^!(\alpha)$ are isomorphic. In either case, by \autoref{194L0}, the morphism $\alpha \colon \mathscr{G}  
  \@ifempty{}{\xrightarrow{\,\sim\,}} 
  {\xrightarrow[\,\sim\,]{}} 
 \mathscr{F}''$ is an isomorphism. Therefore we may let $\delta \mathrel{\mathop:}= \rho \circ \alpha^{-1}$.

\label{194P32}
	Let
	\[ \xymatrix{Y' \ar@{^(->}[r]^-{i'} \ar[d]_{q} \ar@{}[dr]|-*+{\square} & X' \ar[d]^{p} \\ Y \ar@{^(->}[r]^-{i} & X} \]
	be a Cartesian square of schemes satisfying (\dag), $r \mathrel{\mathop:}= p \circ i' = i \circ q$. Assume that $p$ is proper, $i$ is a closed immersion; and there exists an open subset $U$ of $X$ such that $i(Y) = X \setminus U$ and $p$ induces an isomorphism $p^{-1}(U)  
  \@ifempty{}{\xrightarrow{\,\sim\,}} 
  {\xrightarrow[\,\sim\,]{}} 
 U$. Then for each object $\mathscr{F}$ in $\mathbf{D}_{\mathrm{c}}\@ifempty{\mathrm{b}}{}{^{\mathrm{b}}}\@ifnextchar({\b@Brac}{\n@Brac}{X_{\textup{\'et}}, \Lambda}$, there are two distinguished triangles:
	\begin{gather*}
		\mathscr{F} \xrightarrow{\delta_i \oplus \delta_p} i_{\ast} \circ i^{\ast} \mathscr{F} \oplus \mathbf{R}\@ifempty{}{}{^{}} p_{\ast} \circ p^{\ast} \mathscr{F} \xrightarrow{\delta_q \circ \mathrm{pr}_{1} - \delta_{i'} \circ \mathrm{pr}_{2}} \mathbf{R}\@ifempty{}{}{^{}} r_{\ast} \circ r^{\ast} \mathscr{F} \to \mathscr{F}[1]\,, \\
		\mathbf{R}\@ifempty{}{}{^{}} r_{\ast} \circ \mathbf{R}\@ifempty{}{}{^{}} r^! \mathscr{F} \xrightarrow{\vartheta_q \oplus \vartheta_{i'}} i_{\ast} \circ \mathbf{R}\@ifempty{}{}{^{}} i^! \mathscr{F} \oplus \mathbf{R}\@ifempty{}{}{^{}} p_{\ast} \circ \mathbf{R}\@ifempty{}{}{^{}} p^! \mathscr{F} \xrightarrow{-\vartheta_i \circ \mathrm{pr}_{1} + \vartheta_p \circ \mathrm{pr}_{2}} \mathscr{F} \to (\mathbf{R}\@ifempty{}{}{^{}} r_{\ast} \circ \mathbf{R}\@ifempty{}{}{^{}} r^! \mathscr{F})[1] \,,
	\end{gather*}
	in $\mathbf{D}_{\mathrm{c}}\@ifempty{\textbf{+}}{}{^{\textbf{+}}}\@ifnextchar({\b@Brac}{\n@Brac}{X_{\textup{\'et}}, \Lambda}$, where $\delta$ and $\vartheta$ are induced by the adjunctions.

\label{53P5}
	Let the assumptions and the notations be as in \autoref{194P32}; and let $\delta$ be a dimension function on $X$. Then there is a long exact sequence of $\Lambda$-modules:
	\[ \cdots \to \mathrm{H}_{n+1}(X, \delta) \to \mathrm{H}_{n}(Y', \delta) \xrightarrow{q_{\ast} \oplus i'_{\ast}} \mathrm{H}_{n}(Y, \delta) \oplus \mathrm{H}_{n}(X', \delta) \xrightarrow{-i_{\ast} \circ \mathrm{pr}_{1} + p_{\ast} \circ \mathrm{pr}_{2}} \mathrm{H}_{n}(X, \delta) \to \cdots \,. \]

\label{T-P2}
	Let $C$ be a $1$-equidimensional proper algebraic scheme over a separably closed field $k$. Let $C^{(1)}, C^{(2)}, \ldots, C^{(r)}$ be all connected components of $C$; and let $C_1, C_2, \ldots, C_n$ be all irreducible components of $C$. Assume that $\mathrm{H}^{1}(C, \mathcal{O}_C) = 0$. Then we have
	\begin{enumerate}
		\item As to homology, we have
			\begin{enumerate}
				\item There is a canonical isomorphism:
					\[ \mathrm{H}_{0}(C) = \bigoplus^r_{i=1} \mathrm{H}_{0}(C^{(i)})  
  \@ifempty{\oplus \deg}{\xrightarrow{\,\sim\,}} 
  {\xrightarrow[\,\sim\,]{\oplus \deg}} 
 \Lambda^{\oplus r} \,. \]
				\item $\mathrm{H}_{1}(C) = 0$.
				\item $\mathrm{H}_{2}(C)(-1)$ is a free $\Lambda$-module with basis $\mathrm{cl}(C_1),\ldots,\mathrm{cl}(C_n)$.
			\end{enumerate}
		\item As to cohomology, we have
			\begin{enumerate}
				\item There is a canonical isomorphism:
					\[ \mathrm{H}^{0}(C, \Lambda) = \bigoplus^r_{i=1} \mathrm{H}^{0}(C^{(i)})  
  \@ifempty{}{\xrightarrow{\,\sim\,}} 
  {\xrightarrow[\,\sim\,]{}} 
 \Lambda^{\oplus r} \,. \]
				\item $\mathrm{H}^{1}(C, \Lambda) = 0$.
				\item There is a canonical isomorphism $\mathrm{H}^{2}\bigl(C, \Lambda(1)\bigr)  
  \@ifempty{}{\xrightarrow{\,\sim\,}} 
  {\xrightarrow[\,\sim\,]{}} 
 \Lambda^{\oplus n}$ which sends $c_1(\mathscr{L})$ to $\bigl(\deg(\mathscr{L}|_{C_1}), \ldots, \deg(\mathscr{L}|_{C_r})\bigr)$ for each invertible $\mathcal{O}_C$-module $\mathscr{L}$.
			\end{enumerate}
	\end{enumerate}

\label{T-3P8}
	Let $X$ be a surface which is the spectrum of a strictly Henselian local ring, $P$ the closed point of $X$, $U \mathrel{\mathop:}= X \setminus P$. Assume that $U$ is regular, and $X$ admits a desingularization $\pi \colon \widetilde{X} \to X$ which induces an isomorphism $\pi^{-1}(U)  
  \@ifempty{}{\xrightarrow{\,\sim\,}} 
  {\xrightarrow[\,\sim\,]{}} 
 U$. Let $E \mathrel{\mathop:}= \pi^{-1}(P)$ be the exceptional divisor. Then we have
	\begin{enumerate}
		\item The map $\mathrm{H}^{0}(\mathrm{t}_X) \colon \Lambda  
  \@ifempty{}{\xrightarrow{\,\sim\,}} 
  {\xrightarrow[\,\sim\,]{}} 
 \mathrm{H}_{4}(X)(-2)$ is an isomorphism.
		\item $\mathrm{H}_{3}(X)  
  \@ifempty{}{\xrightarrow{\,\sim\,}} 
  {\xrightarrow[\,\sim\,]{}} 
 \mathrm{H}^{1}\bigl(E, \Lambda(2)\bigr)$.
		\item There is an exact sequence of $\Lambda$-modules:
			\[ 0 \to \mathrm{H}_{2}(E) \to \mathrm{H}^{2}\bigl(E, \Lambda(2)\bigr) \to \mathrm{H}_{2}(X) \to \mathrm{H}_{1}(E) \to 0 \,, \]
			Moreover the kernel of the map $\mathrm{H}_{2}(X) \to \mathrm{H}_{1}(E)$ is a finite group.
		\item There is an exact sequence of $\Lambda$-modules:
			\[ 0 \to \mathrm{H}_{1}(X) \to \mathrm{H}_{0}(E) \xrightarrow{\deg} \Lambda \to 0 \,. \]
		\item $\mathrm{H}_{q}(X) = 0$ for $q > 4$ or $q < 1$.
	\end{enumerate}

After applying \autoref{53P5} to the following Cartesian square,
	\begin{equation}\label{E-D2}
		\vcenter{\xymatrix{E \ar@{^(->}[r]^-{\tilde{i}} \ar[d]_{\tau} \ar@{}[dr]|-*+{\square} & \widetilde{X} \ar[d]^{\pi} \\ P \ar@{^(->}[r]^-{i} & X}}
	\end{equation}
	we obtain a long exact sequence
	\begin{equation}\label{E-D3}
		\cdots \to \mathrm{H}_{n+1}(X) \to \mathrm{H}_{n}(E) \to \mathrm{H}_{n}(P) \oplus \mathrm{H}_{n}(\widetilde{X}) \to \mathrm{H}_{n}(X) \to \cdots \,.
	\end{equation}
	For each $q \in \mathbb{Z}$, there is a canonical isomorphism of $\Lambda$-modules:
	\[ \mathrm{H}_{q}(\widetilde{X})  
  \@ifempty{}{\xrightarrow{\,\sim\,}} 
  {\xrightarrow[\,\sim\,]{}} 
 \mathrm{H}^{4-q}\bigl(\widetilde{X}, \Lambda(2)\bigr)  
  \@ifempty{}{\xrightarrow{\,\sim\,}} 
  {\xrightarrow[\,\sim\,]{}} 
 \mathrm{H}^{4-q}\bigl(E, \Lambda(2)\bigr) \,, \]
	where the first isomorphism is induced by \autoref{236P2} (since $\widetilde{X}$ is regular), and the last isomorphism is from the base change theorem via the square \eqref{E-D2}. Thus $\mathrm{H}_{q}(\widetilde{X}) = 0$ for $q < 2$ and $q > 4$. Also note that $\mathrm{H}_{q}(E) = 0$ for $q < 0$ and $q > 2$; and $\mathrm{H}_{q}(P) = \begin{cases} 0 & q \neq 0, \\ \Lambda & q= 0. \end{cases}$ Hence we may divide \eqref{E-D3} to three exact sequences
	\begin{gather} \label{G-E1}
		0 \to \mathrm{H}^{0}\bigl(E, \Lambda(2)\bigr) \to \mathrm{H}_{4}(X) \to 0, \\ \label{G-E2}
		0 \to \mathrm{H}^{1}\bigl(E, \Lambda(2)\bigr) \to \mathrm{H}_{3}(X) \to \mathrm{H}_{2}(E) \to \mathrm{H}^{2}\bigl(E, \Lambda(2)\bigr) \to \mathrm{H}_{2}(X) \to \mathrm{H}_{1}(E) \to 0, \\ \label{G-E3}
		0 \to \mathrm{H}_{1}(X) \to \mathrm{H}_{0}(E) \xrightarrow{\deg} \Lambda \to \mathrm{H}_{0}(X) \to 0.
	\end{gather}
	Now (1) is by the exact sequence \eqref{G-E1}.

	From the sequence \eqref{G-E3}, to prove (4) \& (5) we have only to prove the map $\mathrm{H}_{0}(E) \xrightarrow{\deg} \Lambda$ is epimorphic. Since $X$ is strictly local, the field $k \mathrel{\mathop:}= k(P)$ is separably closed. Let $Q$ be a closed point on $E$. Then $\deg \mathrm{cl}_E(Q) = \bigl[k(Q), k\bigr]$. Put $p \mathrel{\mathop:}= \operatorname{char} k$. Since $k$ is separably closed, the number $\bigl[k(Q), k\bigr]$ is either $1$ or a power of $p$; in both cases, it is invertible on $\Lambda$ (as $\ell \neq p$). Hence $\deg$ is surjective.

	From the sequence \eqref{G-E2}, to prove (2) \& (3) we have only to prove that the homomorphism $\mathrm{H}_{2}(E)(-1) \to \mathrm{H}^{2}\bigl(E, \Lambda(1)\bigr)$ is injective and its cokernel is a torsion group. Let $E_1, E_2, \ldots, E_n$ be all irreducible components of $E$. Then $\mathrm{H}_{2}(E)(-1)$ is a free $\Lambda$-Module with a basis $\bigl\{\mathrm{cl}_E(E_i)\bigr\}^n_{i=1}$. Note that the composite map
	\begin{equation}\label{E-D1}
		\mathrm{H}_{2}(E)(-1) \to \mathrm{H}_{2}(\widetilde{X})(-1)  
  \@ifempty{}{\xrightarrow{\,\sim\,}} 
  {\xrightarrow[\,\sim\,]{}} 
 \mathrm{H}^{2}\bigl(\widetilde{X}, \Lambda(1)\bigr)  
  \@ifempty{}{\xrightarrow{\,\sim\,}} 
  {\xrightarrow[\,\sim\,]{}} 
 \mathrm{H}^{2}\bigl(E, \Lambda(1)\bigr)  
  \@ifempty{\rho}{\xrightarrow{\,\sim\,}} 
  {\xrightarrow[\,\sim\,]{\rho}} 
 \Lambda^{\oplus n}
	\end{equation}
	sends each $\mathrm{cl}_E(E_i)$ to $\sum\limits^n_{j=1}a_{ij}e_j$, where the isomorphism $\rho$ is defined in \cite[IX, 4.7]{SGA4}, $e_1, e_2, \ldots, e_n$ is the standard basis for $\Lambda^{\oplus n}$, and
	\[ a_{ij} = \deg \bigl(\mathscr{L}_{\widetilde{X}}(E_i)|_{E_j}\bigr) = (E_i, E_j) \,, \]
	where $\mathscr{L}_{\widetilde{X}}(E_i)$ means the invertible sheaf on $\widetilde{X}$ associated to the divisor $E_i$. In other words, the map \eqref{E-D1} is given by the intersection matrix $\bigl((E_i, E_j)\bigr)$, which is negative-definite by \cite[(14.1)]{MR0276239}. Therefore the map \eqref{E-D1} is injective with torsion cokernel.

\label{Main-P0}
	Let the assumptions and the notations be as in \autoref{T-3P8}. We further assume that $X$ has a rational singularity at $P$. Then we have
	\begin{enumerate}
		\item Let $\mathrm{Cl}(X)$ denote the Weil divisor class group of $X$. Then there is a canonical isomorphism
			\[ \mathrm{cl} \colon \mathrm{Cl}(X) \otimes_{\mathbb{Z}} \Lambda  
  \@ifempty{}{\xrightarrow{\,\sim\,}} 
  {\xrightarrow[\,\sim\,]{}} 
 \mathrm{H}_{2}(X)(-1) \]
			which sends each $[Y] \otimes 1$ to $\mathrm{cl}_X(Y)$.
		\item The map $\mathrm{H}^{0}(\mathrm{t}_X) \colon \Lambda  
  \@ifempty{}{\xrightarrow{\,\sim\,}} 
  {\xrightarrow[\,\sim\,]{}} 
 \mathrm{H}_{4}(X)(-2)$ is an isomorphism.
		\item $\mathrm{H}_{q}(X) = 0$ for $q \neq 2, 4$.
	\end{enumerate}

\label{M-A21}
	Let $X$ be a surface having only finitely many singular points, all of which are rational singularities. Then $\mathrm{t}_X \colon \mathbb{Q}_{\ell}(2)[4]  
  \@ifempty{}{\xrightarrow{\,\sim\,}} 
  {\xrightarrow[\,\sim\,]{}} 
 \mathscr{K}_X$ is an isomorphism in $\mathbf{D}_{\mathrm{c}}\@ifempty{\mathrm{b}}{}{^{\mathrm{b}}}\@ifnextchar({\b@Brac}{\n@Brac}{X_{\textup{\'et}}, \mathbb{Q}_{\ell}}$. In particular, $\mathbb{Q}_{\ell}$ is a dualizing complex on $X_{\textup{\'et}}$ in coefficient $\mathbb{Q}_{\ell}$.

Let $k$ be a separably closed field on which $\ell$ is invertible. And let $X$ be a surface over $k$. Assume that $X$ has only finitely many singular points, all of which are rational singularities. Then
	\begin{enumerate}
		\item The trace map $\operatorname{Tr}_X \colon \mathrm{H}_{\mathrm{c}}^{4}\bigl(X, \mathbb{Q}_{\ell}(2)\bigr)  
  \@ifempty{}{\xrightarrow{\,\sim\,}} 
  {\xrightarrow[\,\sim\,]{}} 
 \mathbb{Q}_{\ell}$ is an isomorphism.
		\item For every $0 \leqslant r \leqslant 4$ and every object $\mathscr{F}$ in $\mathbf{D}_{\mathrm{c}}\@ifempty{\mathrm{b}}{}{^{\mathrm{b}}}\@ifnextchar({\b@Brac}{\n@Brac}{X_{\textup{\'et}}, \mathbb{Q}_{\ell}}$, the pairing
			\[ \mathrm{H}_{\mathrm{c}}^{r}(X, \mathscr{F}) \times \mathrm{Ext}^{4-r}_X\bigl(\mathscr{F}, \mathbb{Q}_{\ell}(2)\bigr) \to \mathrm{H}_{\mathrm{c}}^{4}\bigl(X, \mathbb{Q}_{\ell}(2)\bigr)  
  \@ifempty{\operatorname{Tr}_X}{\xrightarrow{\,\sim\,}} 
  {\xrightarrow[\,\sim\,]{\operatorname{Tr}_X}} 
 \mathbb{Q}_{\ell} \]
			is nondegenerate.
		\item For every $0 \leqslant r \leqslant 4$, the pairing
			\[ \mathrm{H}_{\mathrm{c}}^{r}(X, \mathbb{Q}_{\ell}) \times \mathrm{H}^{4-r}\bigl(X, \mathbb{Q}_{\ell}(2)\bigr) \to \mathrm{H}_{\mathrm{c}}^{4}\bigl(X, \mathbb{Q}_{\ell}(2)\bigr)  
  \@ifempty{\operatorname{Tr}_X}{\xrightarrow{\,\sim\,}} 
  {\xrightarrow[\,\sim\,]{\operatorname{Tr}_X}} 
 \mathbb{Q}_{\ell} \]
			is nondegenerate.
	\end{enumerate}

(3) is a special case of (2). Let $p \colon X \to \operatorname{Spec} k$ be the structural morphism. By \autoref{M-A21} and \autoref{P-78E}, we have isomorphisms
	\[ \mathbb{Q}_{\ell}(2)[4]  
  \@ifempty{\mathrm{t}_X}{\xrightarrow{\,\sim\,}} 
  {\xrightarrow[\,\sim\,]{\mathrm{t}_X}} 
 \mathscr{K}_X  
  \@ifempty{}{\xrightarrow{\,\sim\,}} 
  {\xrightarrow[\,\sim\,]{}} 
 \mathbf{R}\@ifempty{}{}{^{}} p^! \mathbb{Q}_{\ell} \,. \]
	Hence we have
	\begin{align*}
		\mathrm{Ext}_X^{4-r}\bigl(\mathscr{F}, \mathbb{Q}_{\ell}(2)\bigr) &  
  \@ifempty{}{\xrightarrow{\,\sim\,}} 
  {\xrightarrow[\,\sim\,]{}} 
 \operatorname{Hom}_{\mathbf{D}_{\mathrm{c}}\@ifempty{\mathrm{b}}{}{^{\mathrm{b}}}\@ifnextchar({\b@Brac}{\n@Brac}{X_{\textup{\'et}}, \mathbb{Q}_{\ell}}}\bigl(\mathscr{F}[r], \mathbb{Q}_{\ell}(2)[4]\bigr) \\
		&  
  \@ifempty{}{\xrightarrow{\,\sim\,}} 
  {\xrightarrow[\,\sim\,]{}} 
 \operatorname{Hom}_{\mathbf{D}_{\mathrm{c}}\@ifempty{\mathrm{b}}{}{^{\mathrm{b}}}\@ifnextchar({\b@Brac}{\n@Brac}{X_{\textup{\'et}}, \mathbb{Q}_{\ell}}}\bigl(\mathscr{F}[r], \mathbf{R}\@ifempty{}{}{^{}} p^! \mathbb{Q}_{\ell}\bigr) \\
		&  
  \@ifempty{}{\xrightarrow{\,\sim\,}} 
  {\xrightarrow[\,\sim\,]{}} 
 \operatorname{Hom}_{\mathbf{D}_{\mathrm{c}}\@ifempty{\mathrm{b}}{}{^{\mathrm{b}}}\@ifnextchar({\b@Brac}{\n@Brac}{\mathbb{Q}_{\ell}}}\bigl(\mathbf{R}\@ifempty{}{}{^{}} p_! \mathscr{F}[r], \mathbb{Q}_{\ell}\bigr) \\
		&  
  \@ifempty{}{\xrightarrow{\,\sim\,}} 
  {\xrightarrow[\,\sim\,]{}} 
 \mathrm{H}_{\mathrm{c}}^{r}(X, \mathscr{F})\spcheck \,.
	\end{align*}
	So (2) is proved. In above isomorphism, letting $r = 4$ and $\mathscr{F} = \mathbb{Q}_{\ell}$, we obtain
	\[ \mathrm{H}_{\mathrm{c}}^{4}(X, \mathbb{Q}_{\ell})\spcheck  
  \@ifempty{}{\xrightarrow{\,\sim\,}} 
  {\xrightarrow[\,\sim\,]{}} 
 \mathrm{H}^{0}\bigl(X, \mathbb{Q}_{\ell}(2)\bigr) = \mathbb{Q}_{\ell}(2) \,. \]
	So (1) is proved.

Let $X$ be a surface having only finitely many singular points, all of which are rational singularities. Assume further that for any singular point $P$, $\mathcal{O}_{X, P}^{\mathrm{sh}}$ is factorial. Then $\mathrm{t}_X \colon \mathbb{Z}_{\ell}(2)[4]  
  \@ifempty{}{\xrightarrow{\,\sim\,}} 
  {\xrightarrow[\,\sim\,]{}} 
 \mathscr{K}_X$ is an isomorphism in $\mathbf{D}_{\mathrm{c}}\@ifempty{\mathrm{b}}{}{^{\mathrm{b}}}\@ifnextchar({\b@Brac}{\n@Brac}{X_{\textup{\'et}}, \mathbb{Z}_{\ell}}$. In particular, $\mathbb{Z}_{\ell}$ is a dualizing complex on $X_{\textup{\'et}}$ in coefficient $\mathbb{Z}_{\ell}$.

\label{D-P1}
	Let $X$ be a surface having only finitely many singular points, all of which are rational singularities; $U$ an open dense subset contained in $X_{\mathrm{reg}}$ and $j \colon U \hookrightarrow X$ the inclusion. Let $\mathscr{F}$ be a smooth $\overline{\mathbb{Q}}_{\ell}$-sheaf on $X_{\textup{\'et}}$. Then $\mathscr{F}[2]$ is an object in $\mathrm{Perv}(X, \overline{\mathbb{Q}}_{\ell})$ and there is a canonical isomorphism $j_{! \ast} \circ j^{\ast}\mathscr{F}[2]  
  \@ifempty{}{\xrightarrow{\,\sim\,}} 
  {\xrightarrow[\,\sim\,]{}} 
 \mathscr{F}[2]$.

Obviously we may assume that $U = X_{\mathrm{reg}}$. Then $Y \mathrel{\mathop:}= X \setminus U$ contains only finitely many singular points, all of which are rational singularities of $X$. Let $P$ be a point in $X \setminus U$. Then
	\[ i_P^{\ast}\mathscr{F}[2] = \mathscr{F}_P[2] \in \vphantom{\mathbf{D}}^{\mathrm{P}}\mathbf{D}_{\mathrm{c}}\@ifempty{\mathrm{b}, \leqslant -2}{}{^{\mathrm{b}, \leqslant -2}}\@ifnextchar({\b@Brac}{\n@Brac}{X_{\textup{\'et}}, \overline{\mathbb{Q}}_{\ell}} \,. \]
	Next we calculate $i_P^! \mathscr{F}[2]$. Put $\overline{X} \mathrel{\mathop:}= \operatorname{Spec} \mathcal{O}_{X, P}^{\mathrm{sh}}$, and let $\rho \colon \overline{X} \to X$ and $\iota \colon P \hookrightarrow \overline{X}$ be the canonical morphisms. Since $\overline{X}$ is strictly local and $\mathscr{F}$ is a smooth sheaf, $\rho^{\ast}\mathscr{F}  
  \@ifempty{}{\xrightarrow{\,\sim\,}} 
  {\xrightarrow[\,\sim\,]{}} 
 \overline{\mathbb{Q}}_{\ell}^{\oplus r}$ for some $r \in \mathbb{N}$. So we have
	\begin{alignat*}{2}
		i_P^! \mathscr{F}[2] &= \mathbf{R}\@ifempty{}{}{^{}} \iota^! \circ \rho^{\ast} \mathscr{F}[2]  
  \@ifempty{}{\xrightarrow{\,\sim\,}} 
  {\xrightarrow[\,\sim\,]{}} 
 \mathbf{R}\@ifempty{}{}{^{}} \iota^! \overline{\mathbb{Q}}_{\ell}^{\oplus r}[2] \\
		&  
  \@ifempty{}{\xrightarrow{\,\sim\,}} 
  {\xrightarrow[\,\sim\,]{}} 
 \bigl(\mathbf{R}\@ifempty{}{}{^{}} \iota^! \mathscr{K}_{\overline{X}}(-2)[-4]\bigr)^{\oplus r}[2] & & \qquad (\text{\autoref{M-A21}}) \\
		&= \mathbf{R}\@ifempty{}{}{^{}} \iota^! \mathscr{K}_{\overline{X}}^{\oplus r}(-2)[-2] \\
		&  
  \@ifempty{}{\xrightarrow{\,\sim\,}} 
  {\xrightarrow[\,\sim\,]{}} 
 \mathscr{K}_P^{\oplus r}(-2)[-2] & & \qquad (\text{\autoref{P-78E}}) \\
		&  
  \@ifempty{}{\xrightarrow{\,\sim\,}} 
  {\xrightarrow[\,\sim\,]{}} 
 \overline{\mathbb{Q}}_{\ell}^{\oplus r}(-2)[-2] \,.
	\end{alignat*}
	Hence $i_P^! \mathscr{F}[2] \in \vphantom{\mathbf{D}}^{\mathrm{P}}\mathbf{D}_{\mathrm{c}}\@ifempty{\mathrm{b}, \geqslant 2}{}{^{\mathrm{b}, \geqslant 2}}\@ifnextchar({\b@Brac}{\n@Brac}{X_{\textup{\'et}}, \overline{\mathbb{Q}}_{\ell}}$. This show that $\mathscr{F}[2] \in \mathrm{Perv}(X, \overline{\mathbb{Q}}_{\ell})$.

	Let $i \colon Y \hookrightarrow X$ and $j \colon U \hookrightarrow X$ be the inclusion. Then $i^{\ast}\mathscr{F}[2] \in \vphantom{\mathbf{D}}^{\mathrm{P}}\mathbf{D}_{\mathrm{c}}\@ifempty{\mathrm{b}, \leqslant -2}{}{^{\mathrm{b}, \leqslant -2}}\@ifnextchar({\b@Brac}{\n@Brac}{Y_{\textup{\'et}}, \overline{\mathbb{Q}}_{\ell}}$ and $\mathbf{R}\@ifempty{}{}{^{}} i^! \mathscr{F}[2] \in \vphantom{\mathbf{D}}^{\mathrm{P}}\mathbf{D}_{\mathrm{c}}\@ifempty{\mathrm{b}, \geqslant 2}{}{^{\mathrm{b}, \geqslant 2}}\@ifnextchar({\b@Brac}{\n@Brac}{Y_{\textup{\'et}}, \overline{\mathbb{Q}}_{\ell}}$. So both ${}^{\mathrm{P}}i^{\ast}\mathscr{F}[2]$ and ${}^{\mathrm{P}}i^!\mathscr{F}[2]$ are zero. By \autoref{194L0}, there are two long exact sequences in $\mathrm{Perv}(X, \overline{\mathbb{Q}}_{\ell})$:
	\begin{gather*}
		\cdots \to {}^{\mathrm{P}}j_! \circ j^{\ast}\mathscr{F}[2] \to \mathscr{F}[2] \to i_{\ast} \circ {}^{\mathrm{P}}i^{\ast}\mathscr{F}[2] \to \cdots \,, \\
		\cdots \to i_{\ast} \circ {}^{\mathrm{P}}i^!\mathscr{F}[2] \to \mathscr{F}[2] \to {}^{\mathrm{P}}j_{\ast} \circ j^{\ast}\mathscr{F}[2] \to \cdots \,.
	\end{gather*}
	Thus ${}^{\mathrm{P}}j_! \circ j^{\ast}\mathscr{F}[2] \to \mathscr{F}[2]$ is an epimorphism and $\mathscr{F}[2] \to {}^{\mathrm{P}}j_{\ast} \circ j^{\ast}\mathscr{F}[2]$ is a monomorphism. Therefore $j_{! \ast} \circ j^{\ast}\mathscr{F}[2] = \mathscr{F}[2]$.

Let $X$ be an algebraic scheme over $k$.
	\begin{enumerate}
		\item A constructible $\overline{\mathbb{Q}}_{\ell}$-sheaf $\mathscr{F}$ on $X$ is said to be
			\begin{itemize}
				\item \emph{punctually pure of weight $n$} if for every closed point $x$ on $X$, all eigenvalues of the geometric Frobenius $F_x$ acting on $\mathscr{F}_{\bar{x}}$ are pure of weight $w$;
				\item \emph{mixed} (\emph{of weights $\leqslant w$}), if there exists a finite filtration
					\[ 0 = \mathscr{F}_r \subset \mathscr{F}_{r-1} \subset \cdots \subset \mathscr{F}_1 \subset \mathscr{F}_0 = \mathscr{F} \]
					consisting of constructible $\overline{\mathbb{Q}}_{\ell}$-sheaves, such that each $\mathscr{F}_i/\mathscr{F}_{i+1}$ is punctually pure (of weights $\leqslant n$).
			\end{itemize}
		\item An object $\mathscr{F}$ in $\mathbf{D}_{\mathrm{c}}\@ifempty{\mathrm{b}}{}{^{\mathrm{b}}}\@ifnextchar({\b@Brac}{\n@Brac}{X_{\textup{\'et}}, \widetilde{\mathbb{Q}}_{\ell}}$ is said to be
			\begin{itemize}
				\item \emph{mixed of weights $\leqslant w$} if for every $n \in \mathbb{Z}$, $\mathrm{H}^{n}(\mathscr{F})$ is mixed of weights $\leqslant n+w$;
				\item \emph{mixed of weights $\geqslant w$} if $\mathrm{D}(\mathscr{F}) = \mathbf{R}\mathscr{H}\!om(\mathscr{F}, \mathscr{K}_X)$ is mixed of weights $\leqslant -w$;
				\item \emph{pure of weight $w$} if it is mixed of weights $\leqslant w$ and $\geqslant w$.
			\end{itemize}
	\end{enumerate}
